/* blinddate: a browser-local product prototype. No accounts, charges, bookings, or reports are sent. */
const icons = {
  heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
  spark:'<path d="m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6L12 2Z"/><path d="m20 2 .5 1.5L22 4l-1.5.5L20 6l-.5-1.5L18 4l1.5-.5L20 2Z"/>',
  home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1V10Z"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18m-12 4h.01M12 15h.01M16 15h.01"/>',
  user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
  crown:'<path d="m3 6 4 4 5-7 5 7 4-4-2 13H5L3 6Zm3 10h12"/>',
  shield:'<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4Z"/><path d="m8 12 3 3 5-6"/>',
  pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
  bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-12 9h12m-8 4h4"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>',
  down:'<path d="m6 9 6 6 6-6"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
  leaf:'<path d="M20 3C9 2 2 9 6 16s16 3 14-13Z"/><path d="M4 21 16 9"/>',
  coffee:'<path d="M4 8h12v9a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V8Zm12 1h2a4 4 0 0 1 0 8h-2M7 2v2m5-2v2"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
  settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="15" cy="17" r="3" fill="currentColor" stroke="none"/>',
  flower:'<path d="M12 12c-8-9-12 0-4 2-5 8 5 11 5 3 9 4 12-6 4-6 4-9-7-11-5 1Z"/><circle cx="12" cy="12" r="2"/>',
  people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-2-4"/>',
  logout:'<path d="M9 3H4v18h5m5-15 6 6-6 6m-5-6h11"/>',
  edit:'<path d="m16 3 5 5L9 20l-6 1 1-6L16 3Zm-2 2 5 5"/>',
  star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z"/>',
  flag:'<path d="M4 22V3m0 1c6-4 10 4 16 0v12c-6 4-10-4-16 0"/>',
  copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
  mountain:'<path d="m2 20 7-14 5 9 3-5 5 10H2Zm4-8 3 2 2-2"/>',
  smile:'<circle cx="12" cy="12" r="9"/><path d="M8 14a4 4 0 0 0 8 0M8 8h.01M16 8h.01"/>',
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.spark}</svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const brand = `<svg class="brand-heart" viewBox="0 0 35 35" aria-hidden="true"><path d="M17.5 29S3 20.1 3 11.9C3 4.3 13 1.5 17.5 8.4 22 1.5 32 4.3 32 11.9 32 20.1 17.5 29 17.5 29Z" fill="currentColor"/><path d="m5 14 24 5" fill="none" stroke="#fffdf9" stroke-width="3.5"/></svg>`;
const storageKey = 'blinddate-demo-v1';
const defaultState = () => ({version:1,view:'home',profile:{name:'Jayme',age:25,gender:'Not specified',meet:'Everyone',intent:'A long-term relationship',radius:40,minAge:22,maxAge:32,interests:['Outdoors','Animals','Slow Sundays'],values:['Kindness','Curiosity'],diet:'No restrictions',politics:'Prefer not to say',smoking:'Flexible',complete:false},booking:null,matchIndex:0,plan:'monthly',previewPlan:null,seenNotifications:false});
function readState(){try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved?.version===1&&saved.profile&&Array.isArray(saved.profile.interests)&&Array.isArray(saved.profile.values)){return {...defaultState(),...saved,profile:{...defaultState().profile,...saved.profile},view:['home','dates','profile','membership'].includes(saved.view)?saved.view:'home'};}}catch{}return defaultState();}
let state = readState();
let modal = null;
let notificationsOpen = false;
let lastFocus = null;
let toastTimer;
const app = document.querySelector('#app');
const modalRoot = document.querySelector('#modal-root');
const candidates = [
  {id:'021',gender:'Woman',age:26,km:8,smoking:false,intent:'A long-term relationship',interests:['Outdoors','Animals','Slow Sundays','Cooking'],values:['Kindness','Curiosity','Family']},
  {id:'032',gender:'Man',age:27,km:12,smoking:false,intent:'A long-term relationship',interests:['Arts & culture','Coffee','Animals','Outdoors'],values:['Kindness','Honesty','Curiosity']},
  {id:'048',gender:'Non-binary',age:28,km:18,smoking:false,intent:'A long-term relationship',interests:['Live music','Cooking','Slow Sundays','Travel'],values:['Honesty','Ambition','Curiosity']},
  {id:'055',gender:'Woman',age:24,km:10,smoking:false,intent:'Open to exploring',interests:['Live music','Travel','Coffee','Arts & culture'],values:['Humour','Kindness','Ambition']},
  {id:'063',gender:'Man',age:30,km:15,smoking:false,intent:'Open to exploring',interests:['Fitness','Cooking','Travel','Animals'],values:['Honesty','Family','Kindness']},
];
const venues = [
  {id:'juniper',name:'Juniper & Co.',area:'Mount Pleasant',type:'Seasonal · Cozy & intimate',price:28,rating:'4.8',reviews:214,travel:'18 min for you · 15 min for them',photo:'restaurant.jpg',tags:['Vegetarian','Gluten-free'],description:'Warm lighting, seasonal plates, and a corner table made for a good conversation.'},
  {id:'olive',name:'Olive & Oak',area:'Kitsilano',type:'Mediterranean · Relaxed',price:32,rating:'4.7',reviews:186,travel:'24 min for you · 20 min for them',photo:'bistro.jpg',tags:['Vegetarian','Gluten-free'],description:'A relaxed neighborhood bistro with shareable plates and plenty of natural light.'},
  {id:'sunday',name:'Sunday Social',area:'Main Street',type:'Café · Easygoing',price:16,rating:'4.8',reviews:302,travel:'16 min for you · 17 min for them',photo:'cafe.jpg',tags:['Vegetarian'],description:'Coffee, a little something sweet, and a low-pressure way to meet.'},
  {id:'fig',name:'The Little Fig',area:'Fairview',type:'Plant-based · Thoughtful',price:25,rating:'4.6',reviews:128,travel:'22 min for you · 19 min for them',photo:'bistro.jpg',tags:['Vegetarian','Gluten-free'],description:'Bright, plant-forward dishes in a friendly, welcoming dining room.'},
  {id:'common',name:'Common Ground',area:'Commercial Drive',type:'Coffee & small plates · Casual',price:19,rating:'4.7',reviews:241,travel:'20 min for you · 23 min for them',photo:'cafe.jpg',tags:['Vegetarian'],description:'An unhurried café for that first hello, with food if you decide to stay.'},
];
const interestOptions = ['Outdoors','Animals','Slow Sundays','Cooking','Travel','Fitness','Arts & culture','Live music','Coffee'];
const valueOptions = ['Kindness','Curiosity','Honesty','Humour','Ambition','Family'];
function eligibleMatches(profile=state.profile){return candidates.filter(person=>(profile.meet==='Everyone'||person.gender===profile.meet)&&person.age>=profile.minAge&&person.age<=profile.maxAge&&person.km<=profile.radius&&(profile.smoking!=='Non-smoker only'||!person.smoking)&&(profile.intent==='Open to exploring'||person.intent===profile.intent)).map(person=>({...person,score:person.interests.filter(x=>profile.interests.includes(x)).length*2+person.values.filter(x=>profile.values.includes(x)).length*3})).sort((a,b)=>b.score-a.score);}
function currentMatch(){const matches=eligibleMatches();return matches.length?matches[state.matchIndex%matches.length]:null;}
function matchTags(){const match=currentMatch();if(!match)return [];const shared=state.profile.interests.filter(x=>match.interests.includes(x));return shared.length?shared.slice(0,3):['Shared intentions','Close to home'];}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('Your browser could not save changes. This demo still works for this visit.');}}
function dateLabel(timestamp,options={weekday:'short',month:'short',day:'numeric'}){return new Intl.DateTimeFormat('en-CA',{...options,timeZone:'America/Vancouver'}).format(new Date(timestamp));}
function timeLabel(timestamp){return new Intl.DateTimeFormat('en-CA',{hour:'numeric',minute:'2-digit',timeZone:'America/Vancouver'}).format(new Date(timestamp));}
function venueById(id){return venues.find(v=>v.id===id)||venues[0];}
function toast(message){const target=document.querySelector('#toast');target.textContent=message;target.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>target.classList.remove('visible'),4300);}
function navItem(view,label,graphic,mobile=false){return `<button class="${mobile?'':'nav-button '}${state.view===view?'active':''}" data-action="navigate" data-view="${view}" ${state.view===view?'aria-current="page"':''}>${icon(graphic)}<span>${label}</span>${view==='dates'&&(state.booking||currentMatch())?'<span class="nav-count">1</span>':''}</button>`;}
function render(){
  app.innerHTML=`<div class="shell"><aside class="sidebar"><button class="wordmark" data-action="navigate" data-view="home" aria-label="blinddate home">${brand}<span>blinddate<span class="brand-dot">.</span></span></button><p class="brand-tagline">Less scrolling. More butterflies.</p><p class="nav-label">YOUR NEXT CHAPTER</p><nav class="nav" aria-label="Main navigation">${navItem('home','For you','spark')}${navItem('dates','Your date','calendar')}${navItem('profile','Your world','user')}${navItem('membership','Membership','crown')}</nav><div class="sidebar-bottom"><div class="membership-teaser">${icon('flower')}<h3>A little more possibility.</h3><p>Your first introduction is on us.<br>See where the next one takes you.</p><button class="text-link" data-action="navigate" data-view="membership">Explore membership ${icon('arrow')}</button></div><button class="safety-link" data-action="safety">${icon('shield')} Your comfort comes first</button><p class="demo-note">INTERACTIVE PROTOTYPE · LOCAL DATA</p></div></aside><main class="workspace"><header class="topbar"><span class="breadcrumb">${{home:'A little mystery. A real connection.',dates:'Make room for a real connection.',profile:'The little things that make you, you.',membership:'More possibilities, at your pace.'}[state.view]}</span><button class="wordmark mobile-brand" data-action="navigate" data-view="home" aria-label="blinddate home">${brand}<span>blinddate<span class="brand-dot">.</span></span></button><div class="top-actions"><button class="location-button" data-action="location">${icon('pin')} Vancouver, BC ${icon('down')}</button><div class="notification-container"><button class="icon-button" data-action="notifications" aria-label="Notifications" aria-expanded="${notificationsOpen}">${icon('bell')}${!state.seenNotifications?'<span class="notification-dot"></span>':''}</button>${notificationsOpen?`<div class="notification-menu"><h3>A little spark for you.</h3><p>${state.booking?'Your demo date is confirmed. You can review the details and cancellation deadline in Your date.':'A sample introduction is ready. Discover the things you have in common before you plan a date.'}</p><button class="text-link" data-action="navigate" data-view="dates">Take a look ${icon('arrow')}</button></div>`:''}</div><button class="avatar" data-action="navigate" data-view="profile" aria-label="Your profile">${esc(state.profile.name.charAt(0).toUpperCase())}</button></div></header><div id="page-content" class="fade-in">${({home:homePage,dates:datePage,profile:profilePage,membership:membershipPage}[state.view])()}</div><footer class="bottom-note"><span>${icon('lock')} Prototype · sample people & venues · no real bookings</span><em>Meet the person. Skip the profile.</em></footer></main><nav class="mobile-nav" aria-label="Mobile navigation">${navItem('home','For you','spark',true)}${navItem('dates','Your date','calendar',true)}${navItem('profile','Your world','user',true)}${navItem('membership','Membership','crown',true)}</nav></div>`;
  updateCountdown();
}
function heroIllustration(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 400 290"><defs><pattern id="grain" width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".55" fill="#765c45" opacity=".06"/></pattern><linearGradient id="arch" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f0c8af"/><stop offset="1" stop-color="#f7e8cf"/></linearGradient></defs><ellipse cx="210" cy="258" rx="126" ry="15" fill="#d4b3a0" opacity=".16"/><path d="M91 260V141a114 114 0 0 1 228 0v119Z" fill="url(#arch)"/><path d="M91 260V141a114 114 0 0 1 228 0v119Z" fill="url(#grain)"/><path d="M140 260v-97a69 69 0 0 1 138 0v97" fill="none" stroke="#f8edd9" stroke-width="1.1" opacity=".7"/><path d="M79 270c13-26 30-50 54-70l45-24 21 31-34 35-20 28Z" fill="#bd775a"/><path d="m178 176 16-11c7-5 15-1 14 5l-8 13c16-8 23-4 20 3l-19 20c-7 7-16 8-24 2l-13-13Z" fill="#d99b75"/><path d="M257 270c-4-24-22-48-35-64l25-29 42 26c17 13 36 37 46 67Z" fill="#643d47"/><path d="m246 177-13-10c-7-5-15-2-15 5l5 12c-15-9-24-6-21 1l19 21c6 8 16 9 23 3l15-13Z" fill="#d99b75"/><g transform="translate(144 118) rotate(-14 30 35)"><path d="M13 15h55l-5 49c-1 9-9 14-22 14S20 73 19 64Z" fill="#f8eedb"/><path d="M68 25h9c18 0 18 29 2 31H65" fill="none" stroke="#f8eedb" stroke-width="9"/><ellipse cx="40" cy="15" rx="27" ry="7" fill="#d7b48e"/><ellipse cx="40" cy="15" rx="21" ry="4" fill="#956b52"/><path d="M26 6c-8-10 9-12 1-23m18 22c-7-8 8-11 3-20" fill="none" stroke="#fff8e8" stroke-width="2" opacity=".8"/></g><g transform="translate(227 121) rotate(15 30 30)"><path d="M9 11h51l-5 48c-1 9-9 14-21 14S15 68 14 59Z" fill="#d8856a"/><path d="M60 22h7c17 0 16 28 0 28h-9" fill="none" stroke="#d8856a" stroke-width="9"/><ellipse cx="34.5" cy="11" rx="25.5" ry="6" fill="#ae6854"/><ellipse cx="34.5" cy="11" rx="20" ry="3.8" fill="#714d43"/><path d="M25 1c-8-10 8-12 1-23m16 21c-5-8 8-11 3-20" fill="none" stroke="#fce9cd" stroke-width="2" opacity=".8"/></g><path d="M201 88c-15-12-18 5-9 9l9 5 8-10c7-10-5-16-8-4Z" fill="#d97760" transform="rotate(-14 200 92)"/><path d="m103 65 2 8 8 2-8 2-2 8-2-8-8-2 8-2Zm212 33 2 8 8 2-8 2-2 8-2-8-8-2 8-2Z" fill="#ba8564"/><path d="m280 47 1 5 5 1-5 1-1 5-1-5-5-1 5-1Z" fill="#faf2df"/><path d="m75 169-3 6m-2-21-7 2m264 29 6-2m-2-12 5 3" stroke="#c28a70" stroke-width="1.5" stroke-linecap="round"/><path d="M101 237c-6-24-21-34-33-34 2 16 17 30 33 34Z" fill="#9ca182"/><path d="M104 250c-2-14 1-27 11-35 5 15 0 28-11 35Z" fill="#adb092"/><path d="m103 261-2-27m218 19c2-15 9-24 20-27-1 13-8 23-20 27Z" stroke="#8e977a" stroke-width="1.2" fill="none"/></svg><span class="art-caption">A good story starts with showing up.</span></div>`;}
function homePage(){const match=currentMatch();return `<div class="page-heading"><div><p class="greeting">A little possibility, ${esc(state.profile.name)} ${icon('sun')}</p><h1>Good things start with <em>hello.</em></h1></div><span class="tiny-pill online"><span class="online-dot"></span> Open to a little magic</span></div><section class="hero"><div class="hero-copy"><span class="hero-label">${icon('spark')} LESS SWIPING. MORE SOMETHING REAL.</span><h2>Your kind of person.<br><em>A little mystery.</em></h2><p>We find the connection. You bring yourself.<br>Let’s see what happens over a first hello.</p><button class="button dark" data-action="${state.profile.complete?'plan':'onboarding'}">${state.profile.complete?'Find my connection':'Find your kind of connection'} ${icon('arrow')}</button></div>${heroIllustration()}</section><div class="section-heading"><h2>A spark, just for you<span class="little-star">✧</span></h2><p>Thoughtfully matched. Never rushed.</p></div><div class="connection-grid"><article class="match-card"><div class="mystery-portrait"><div class="mystery-seal">${icon('spark')}</div><span class="mystery-caption">A LITTLE MYSTERY.<br>A REAL PERSON.</span></div><div class="match-content"><span class="match-kicker">${icon('heart')} ${state.booking?'YOUR NEXT HELLO IS SET':match?'YOUR FIRST INTRODUCTION IS ON US':'LET’S FIND YOUR FIT'}</span><h3>${state.booking?'Something to look forward to.':match?'Your next maybe.':'Room for possibility.'}</h3><p class="match-description">${state.booking?'A place, a time, and someone new. All that’s left is showing up as you.':match?'A few things in common. A whole person to discover. Meet someone who gets your kind of life.':'No sample person meets these preferences yet. Try a wider age range or travel radius.'}</p><div class="tag-row">${matchTags().map((tag,i)=>`<span class="tag">${icon(['mountain','heart','coffee'][i%3])}${esc(tag)}</span>`).join('')}</div><div class="match-footer"><button class="button primary" data-action="${state.booking?'navigate':match?'plan':'onboarding'}" ${state.booking?'data-view="dates"':''}>${state.booking?'See your date':match?'Let’s plan a date':'Edit preferences'} ${icon('arrow')}</button>${match&&!state.booking?'<button class="text-link" data-action="why">Why this match?</button>':''}</div></div></article><button class="venue-teaser" data-action="plan"><div class="venue-photo"><img src="assets/restaurant.jpg" alt="A warmly lit restaurant set for a first date"><span class="photo-badge">${icon('pin')} 5 thoughtfully picked spots</span><span class="photo-corner">GOOD FOOD. BETTER COMPANY.</span></div><div class="venue-teaser-copy"><h3>A date, without the debate.</h3><p>Cozy corners. Your kind of food.<br>Somewhere that works for you both.</p><span class="round-arrow">${icon('arrow')}</span></div></button></div><section class="steps-section"><div class="steps-header"><h2>A little less complicated.</h2><button class="text-link" data-action="how">How it works ${icon('arrow')}</button></div>${stepsMarkup()}</section>`;}
function stepsMarkup(){return `<div class="steps-grid"><div class="step-card"><span class="step-icon">${icon('user')}</span><div><h3>01. Be a little you.</h3><p>Your values, your quirks, your kind of person.<br>We start with what matters.</p></div></div><div class="step-card"><span class="step-icon">${icon('spark')}</span><div><h3>02. Leave room for surprise.</h3><p>A thoughtful match, without the profiles.<br>Connection comes before the photo.</p></div></div><div class="step-card"><span class="step-icon">${icon('coffee')}</span><div><h3>03. Take it into the real world.</h3><p>Pick a place and a time that feel right.<br>We’ll take care of the little details.</p></div></div></div>`;}
function datePage(){if(!state.booking)return `<div class="page-heading"><div><p class="greeting">A first hello is a few steps away.</p><h1>Let’s make it <em>a date.</em></h1></div></div><section class="surface empty-date"><div class="empty-icon">${icon('calendar')}</div><h2>A little planning.<br>A lot of possibility.</h2><p>Your introduction is ready. Choose somewhere you’d both feel comfortable, find a time, and let the story start.</p><button class="button primary" data-action="plan">Plan your first date ${icon('arrow')}</button><p class="small-print" style="margin-top:18px;margin-bottom:0">Your first service fee is C$0. Food and drinks are paid separately.</p></section>`;
 const booking=state.booking,venue=venueById(booking.venueId);return `<div class="page-heading"><div><p class="greeting">There’s a hello on the horizon.</p><h1>Something to <em>look forward to.</em></h1></div><span class="tiny-pill online">${icon('check')} Demo date confirmed</span></div><div class="page-grid"><section class="surface"><img class="date-photo" src="assets/${venue.photo}" alt="Sample dining room for ${esc(venue.name)}"><span class="status-badge">${icon('check')} SIMULATED CONFIRMATION</span><h2 class="booking-title">${esc(venue.name)}, and a little spark.</h2><p class="profile-note">Your mystery match #${esc(booking.matchId)} is part of this demo. No restaurant reservation has been made.</p><div class="booking-meta"><div>${icon('calendar')} ${dateLabel(booking.timestamp,{weekday:'long',month:'long',day:'numeric'})} · ${timeLabel(booking.timestamp)} PT</div><div>${icon('pin')} ${esc(venue.area)}, Vancouver · sample venue</div><div>${icon('people')} Two seats. One new beginning.</div><div>${icon('coffee')} Budget around C$${venue.price} per person, paid separately</div></div><div class="booking-actions"><button class="button primary" data-action="share">${icon('copy')} Copy date details</button><button class="button secondary" data-action="reschedule">Change date ${icon('calendar')}</button></div></section><div><section class="surface"><span class="eyebrow muted">YOUR NEXT FIRST HELLO</span><p class="countdown" data-countdown></p><p class="small-print">until your demo date</p><div class="profile-section"><h3>Plans can change.</h3><p class="small-print">Free cancellation until <strong>${dateLabel(booking.timestamp-86400000)} at ${timeLabel(booking.timestamp-86400000)} PT</strong>. A C$20 fee would apply afterward, with safety and emergency exceptions. No charges are made in this prototype.</p><button class="text-link danger space-top" data-action="cancel">Cancel this date</button></div></section><section class="surface space-top profile-note">${icon('shield')}<h3>Your comfort comes first.</h3><p>Meet in public, keep your own way home, and share your plans with someone you trust. You can leave at any time.</p><button class="text-link space-top" data-action="safety">Visit the comfort corner ${icon('arrow')}</button></section></div></div>`;}
function profilePage(){const p=state.profile;return `<div class="page-heading"><div><p class="greeting">The person behind the possibility.</p><h1>Your world. <em>Your kind of love.</em></h1></div><button class="button secondary" data-action="onboarding">${icon('edit')} Edit your world</button></div><div class="page-grid"><section class="surface"><div class="profile-top"><div class="profile-large-avatar">${esc(p.name.charAt(0).toUpperCase())}</div><div><h2 class="profile-name">${esc(p.name)}, ${esc(p.age)}</h2><p class="profile-summary">Vancouver, BC · Your profile stays private</p></div></div><div class="progress-label"><span>${p.complete?'Your world is ready':'A few more little things to discover'}</span><span>${p.complete?'100%':'60%'}</span></div><div class="progress-track"><div class="progress-fill" style="width:${p.complete?'100':'60'}%"></div></div><div class="profile-section"><h3>The things that light you up.</h3><div class="tag-row">${p.interests.map(x=>`<span class="tag">${icon('spark')}${esc(x)}</span>`).join('')}</div><p class="profile-note">${p.values.map(esc).join(' · ')}</p></div><div class="profile-section"><h3>A connection that fits your life.</h3><div class="detail-row"><span>You’re looking for</span><span>${esc(p.intent)}</span></div><div class="detail-row"><span>You’d like to meet</span><span>${esc(p.meet)}</span></div><div class="detail-row"><span>Age preference</span><span>${p.minAge}–${p.maxAge}</span></div><div class="detail-row"><span>Travel radius</span><span>Up to ${p.radius} km</span></div><div class="detail-row"><span>Dietary needs</span><span>${esc(p.diet)}</span></div><div class="detail-row"><span>Smoking preference</span><span>${esc(p.smoking)}</span></div></div><button class="button secondary full-width space-top" data-action="onboarding">A little more about me ${icon('arrow')}</button></section><div><section class="surface profile-note">${icon('lock')}<h3>A little mystery.<br>A lot of respect.</h3><p>Your answers help us find common ground. Your photo and full profile aren’t shown to a match. Political preferences are optional and stay private.</p><p class="space-top">This prototype saves your answers in this browser only. Identity checks and live matchmaking aren’t connected.</p><button class="text-link space-top" data-action="safety">Your privacy & comfort ${icon('arrow')}</button></section><section class="surface space-top profile-note"><h3>A fresh start?</h3><p>Clear your saved demo preferences, date, and membership selection from this browser.</p><button class="text-link space-top" data-action="reset">Reset the demo ${icon('arrow')}</button></section></div></div>`;}
function membershipPage(){const annual=state.plan==='annual';return `<div class="page-heading"><div><p class="greeting">A little more room for possibility.</p><h1>Real connections. <em>Simple plans.</em></h1><p class="subheading">Your first introduction is on us. After that, keep meeting at your own pace.</p></div></div><div class="plan-switch" role="group" aria-label="Billing interval"><button data-action="billing" data-value="monthly" class="${!annual?'selected':''}" aria-pressed="${!annual}">Monthly</button><button data-action="billing" data-value="annual" class="${annual?'selected':''}" aria-pressed="${annual}">Yearly · save 17%</button></div><div class="pricing-grid"><section class="pricing-card"><h2>A first hello.</h2><p>One introduction. A little possibility.</p><div class="price">C$0<span> / your first date</span></div><ul class="feature-list"><li>${icon('check')} One personality-first introduction</li><li>${icon('check')} Venue and time planning</li><li>${icon('check')} Comfort and reporting tools</li><li>${icon('check')} No automatic subscription</li></ul><button class="button secondary" data-action="plan">Find your first hello ${icon('arrow')}</button></section><section class="pricing-card featured"><span class="plan-badge">KEEP THE POSSIBILITIES OPEN</span><h2>A little more magic.</h2><p>Thoughtful introductions, at your pace.</p><div class="price">C$${annual?'299.99':'29.99'}<span> / ${annual?'year':'month'}</span></div><p>${annual?'C$299.99 billed yearly. About C$25/month.':'C$29.99 billed monthly. Cancel renewal anytime.'}</p><ul class="feature-list"><li>${icon('check')} Two arranged-date credits each month</li><li>${icon('check')} Personalized, private introductions</li><li>${icon('check')} Venue and schedule coordination</li><li>${icon('check')} The same comfort tools on every plan</li></ul><button class="button primary" data-action="select-plan">Preview ${annual?'yearly':'monthly'} membership ${icon('arrow')}</button></section></div>${state.previewPlan?`<p class="plan-selected">${esc(state.previewPlan==='annual'?'Yearly':'Monthly')} membership selected for preview. You have not subscribed or been charged.</p>`:''}<p class="pricing-note">All prices are CAD, before tax. Food and drinks are separate. Membership, checkout, and cancellation fees are demonstrations only. No payment details are collected.</p>`;}
function openModal(type,extra={}){if(!modal){lastFocus=document.activeElement;}modal={type,...extra};notificationsOpen=false;renderModal();document.body.style.overflow='hidden';requestAnimationFrame(()=>modalRoot.querySelector('input:not([type="checkbox"]), select, .choice, .venue-option, .button, .dialog-close')?.focus());}
function closeModal(){modal=null;modalRoot.innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
function modalFrame(body,small=false){return `<div class="dialog-backdrop"><section class="dialog ${small?'small':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><button class="icon-button dialog-close" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>${body}</section></div>`;}
function renderModal(){if(!modal)return;const active=document.activeElement;const focusId=modalRoot.contains(active)?active.id:null;const focusData=modalRoot.contains(active)&&active.dataset.action?{...active.dataset}:null;const scrollTop=modalRoot.querySelector('.dialog')?.scrollTop||0;let body='';let small=false;switch(modal.type){case'onboarding':body=onboardingModal();break;case'planner':body=plannerModal();break;case'why':body=whyModal();small=true;break;case'how':body=`<p class="dialog-eyebrow">${icon('spark')} A DIFFERENT WAY TO MEET</p><h2 id="dialog-title">Less scrolling.<br>More butterflies.</h2><p class="dialog-description">A little intention goes a long way. Here’s how we take things from a maybe to a first hello.</p><div class="how-modal-steps">${stepsMarkup()}</div><div class="inline-note">${icon('shield')}You choose whether to meet. No fee applies before a date is booked. You can always leave a date.</div><div class="dialog-footer"><span class="small-print">First introduction: C$0 service fee</span><button class="button primary" data-action="onboarding">Let’s start with you ${icon('arrow')}</button></div>`;break;case'safety':body=safetyModal();small=true;break;case'cancel':body=cancelModal();small=true;break;case'plan-preview':body=`<p class="dialog-eyebrow">${icon('crown')} A LITTLE MORE POSSIBILITY</p><h2 id="dialog-title">Make room for<br>your next chapter.</h2><p class="dialog-description">${state.plan==='annual'?'C$299.99/year, billed upfront':'C$29.99/month'}, before tax. Two date credits each month, with food and drinks paid separately.</p><div class="notice-card"><h3>You’re just trying things on.</h3><p>This is a membership preview. No subscription is started, no payment details are collected, and no money is charged.</p></div><div class="dialog-footer"><button class="button ghost" data-action="close-modal">Maybe later</button><button class="button primary" data-action="confirm-plan">Select for demo ${icon('check')}</button></div>`;small=true;break;case'reset':body=`<p class="dialog-eyebrow">${icon('flower')} BEGIN AGAIN</p><h2 id="dialog-title">A clean slate?</h2><p class="dialog-description">This clears your saved demo date, preferences, and plan selection from this browser. You’ll return to the sample profile.</p><div class="dialog-footer"><button class="button secondary" data-action="close-modal">Keep exploring</button><button class="button dark" data-action="confirm-reset">Reset demo</button></div>`;small=true;break;case'report':body=`<p class="dialog-eyebrow">${icon('flag')} YOUR VOICE MATTERS</p><h2 id="dialog-title">Tell us what happened.</h2><p class="dialog-description">This form previews the reporting experience. Reports are not transmitted or monitored in this prototype.</p><label class="field-label" for="report-category">What would you like to report?</label><select id="report-category" class="input"><option>Something made me uncomfortable</option><option>A person didn’t attend</option><option>A profile or identity concern</option><option>A venue concern</option></select><label class="field-label" for="report-details">A little context (optional)</label><textarea class="input" id="report-details" placeholder="Use sample details while trying this prototype."></textarea><div class="dialog-footer"><button class="button ghost" data-action="safety">Back</button><button class="button primary" data-action="demo-report">Preview report receipt ${icon('arrow')}</button></div>`;small=true;break;case'report-receipt':body=`<p class="dialog-eyebrow">${icon('check')} REPORT PREVIEW</p><h2 id="dialog-title">This is where<br>we’d listen.</h2><p class="dialog-description">In the live service, your report would go to the support team. In this prototype, nothing has been sent and the report contents have not been saved.</p><button class="button primary" data-action="close-modal">Back to exploring</button>`;small=true;break;}
modalRoot.innerHTML=modalFrame(body,small);const focusTarget=focusId?modalRoot.querySelector('#'+CSS.escape(focusId)):focusData?[...modalRoot.querySelectorAll('[data-action]')].find(el=>el.dataset.action===focusData.action&&el.dataset.value===focusData.value&&el.dataset.group===focusData.group):null;const dialog=modalRoot.querySelector('.dialog');dialog.scrollTop=scrollTop;(focusTarget||dialog).focus({preventScroll:true});}
function wizardProgress(step,count){return `<div class="wizard-steps" aria-label="Step ${step+1} of ${count}">${Array.from({length:count},(_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div>`;}
function choices(options,selected,group,multi=false){return `<div class="choice-group" role="group" aria-label="${esc(group)}">${options.map(value=>`<button class="choice ${(multi?selected.includes(value):selected===value)?'selected':''}" aria-pressed="${multi?selected.includes(value):selected===value}" data-action="profile-choice" data-group="${group}" data-value="${esc(value)}" ${multi?'data-multi="true"':''}>${esc(value)}</button>`).join('')}</div>`;}
function onboardingModal(){const p=modal.draft,step=modal.step;let fields='';if(step===0)fields=`<p class="dialog-eyebrow">01 / THE PERSON BEHIND THE POSSIBILITY</p><h2 id="dialog-title">Let’s start with you.</h2><p class="dialog-description">The good stuff starts with being yourself. Your full profile stays private. Use sample information while exploring.</p><div class="field-grid"><div><label class="field-label" for="profile-name">First name</label><input class="input" id="profile-name" data-profile-field="name" value="${esc(p.name)}" maxlength="30" autocomplete="given-name" required></div><div><label class="field-label" for="profile-age">Your age · adults only</label><input class="input" id="profile-age" data-profile-field="age" type="number" min="18" max="100" value="${p.age}" required></div></div><label class="field-label" for="profile-gender">I describe myself as</label><select class="input" id="profile-gender" data-profile-field="gender">${['Not specified','Man','Woman','Non-binary'].map(v=>`<option ${p.gender===v?'selected':''}>${v}</option>`).join('')}</select><label class="field-label">I’d like to meet</label>${choices(['Everyone','Man','Woman','Non-binary'],p.meet,'meet')}<label class="field-label">I’m looking for</label>${choices(['A long-term relationship','Open to exploring'],p.intent,'intent')}`;
if(step===1)fields=`<p class="dialog-eyebrow">02 / THE LITTLE THINGS</p><h2 id="dialog-title">What lights you up?</h2><p class="dialog-description">Select the things you enjoy and the qualities you value. We’ll look for common ground, with room for a little surprise.</p><label class="field-label">My kind of good time · choose a few</label>${choices(interestOptions,p.interests,'interests',true)}<label class="field-label">The qualities I value</label>${choices(valueOptions,p.values,'values',true)}<label class="field-label" for="profile-diet">When we pick a place, keep in mind</label><select class="input" id="profile-diet" data-profile-field="diet">${['No restrictions','Vegetarian','Vegan','Gluten-free'].map(v=>`<option ${p.diet===v?'selected':''}>${v}</option>`).join('')}</select><label class="field-label" for="profile-politics">Political compatibility · optional, private</label><select class="input" id="profile-politics" data-profile-field="politics">${['Prefer not to say','Similar views matter to me','Open to different views'].map(v=>`<option ${p.politics===v?'selected':''}>${v}</option>`).join('')}</select><p class="small-print" style="margin-top:8px">This prototype stores this preference locally; political matching is not implemented.</p>`;
if(step===2)fields=`<p class="dialog-eyebrow">03 / A CONNECTION THAT FITS</p><h2 id="dialog-title">Close enough for hello.</h2><p class="dialog-description">A match should work for your life, too. We’ll use these preferences to filter the sample introductions.</p><label class="field-label" for="profile-radius">My travel radius · <span id="radius-value">${p.radius}</span> km from Vancouver</label><input id="profile-radius" class="range-input" data-profile-field="radius" type="range" min="5" max="50" step="5" value="${p.radius}"><div class="range-labels"><span>Closer to home · 5 km</span><span>A little adventure · 50 km</span></div><label class="field-label">Age range I’d like to meet</label><div class="field-grid"><div><label class="field-label" for="profile-min-age">From</label><input id="profile-min-age" class="input" data-profile-field="minAge" type="number" min="18" max="100" value="${p.minAge}" required></div><div><label class="field-label" for="profile-max-age">To</label><input id="profile-max-age" class="input" data-profile-field="maxAge" type="number" min="18" max="100" value="${p.maxAge}" required></div></div><label class="field-label">Smoking preference</label>${choices(['Flexible','Non-smoker only'],p.smoking,'smoking')}<div class="inline-note">${icon('lock')}Your preferences stay private. You’ll see why an introduction could fit, without browsing their profile.</div>`;
return `${wizardProgress(step,3)}${fields}<div class="dialog-footer"><button class="button ghost" data-action="${step?'onboarding-back':'close-modal'}">${step?'← Back':'Maybe later'}</button><button class="button primary" data-action="onboarding-next">${step===2?'Find my kind of connection':'A little more about me'} ${icon('arrow')}</button></div>`;}
function plannerModal(){const step=modal.step,venue=modal.venueId?venueById(modal.venueId):null;let fields='';if(step===0){let filtered=venues.filter(v=>(modal.filter==='Under $30'?v.price<30:modal.filter==='All spots'||v.tags.includes(modal.filter))&&(state.profile.diet!=='Gluten-free'||v.tags.includes('Gluten-free')));fields=`<p class="dialog-eyebrow">${icon('pin')} 01 / PICK YOUR CORNER OF THE WORLD</p><h2 id="dialog-title">Somewhere for a first hello.</h2><p class="dialog-description">Five sample spots, thoughtfully balanced for food, budget, and travel. Choose a place you’d feel comfortable. Venue details, ratings, and travel times are fictional demo data.</p><div class="filter-row" role="group" aria-label="Venue filters">${['All spots','Vegetarian','Gluten-free','Under $30'].map(f=>`<button data-action="venue-filter" data-value="${f}" class="${modal.filter===f?'selected':''}" aria-pressed="${modal.filter===f}">${f}</button>`).join('')}</div><div class="venue-grid">${filtered.map(v=>`<button class="venue-option ${modal.venueId===v.id?'selected':''}" data-action="venue-select" data-value="${v.id}" aria-pressed="${modal.venueId===v.id}" aria-label="Select ${v.name}"><img src="assets/${v.photo}" alt="Illustrative ${v.type.split(' · ')[0].toLowerCase()} dining space"><span class="selection-mark">${icon('check')}</span><div class="venue-option-content"><h3>${v.name}</h3><p>${v.area} · ${v.type}<br>${v.tags.join(' · ')}</p><div class="venue-option-details"><span>★ ${v.rating} (${v.reviews})</span><span>~C$${v.price} / person</span></div></div></button>`).join('')}</div><div class="inline-note">${icon('shield')}Public, staffed spaces with easy ways home. Dietary tags are examples; serious allergies require direct venue confirmation. Vegan suitability isn’t verified in this demo.</div>`;}
if(step===1)fields=`<p class="dialog-eyebrow">${icon('calendar')} 02 / MAKE A LITTLE TIME</p><h2 id="dialog-title">When does hello work?</h2><p class="dialog-description">Choose from sample overlapping availability. Your match’s acceptance is simulated. All times are Vancouver time.</p><div class="review-venue"><img src="assets/${venue.photo}" alt="Illustration of your selected dining space"><div><h3>${venue.name}</h3><p>${venue.area} · ${venue.travel}</p></div></div><label class="field-label">A day to look forward to</label><div class="date-choices">${availableDays().map((day,i)=>`<button class="day-choice ${modal.dayIndex===i?'selected':''}" data-action="day-select" data-value="${i}" aria-pressed="${modal.dayIndex===i}"><span>${dateLabel(day,{weekday:'short'})}</span><strong>${dateLabel(day,{day:'numeric'})}</strong><span>${dateLabel(day,{month:'short'})}</span></button>`).join('')}</div><label class="field-label">Your first hello, at</label><div class="choice-group" role="group" aria-label="Time of date">${['12:00','17:30','18:30','19:00'].map(t=>`<button class="choice ${modal.time===t?'selected':''}" data-action="time-select" data-value="${t}" aria-pressed="${modal.time===t}">${displayTime(t)}</button>`).join('')}</div><div class="inline-note">${icon('clock')}A first meeting can be just 45–60 minutes. Stay a little longer if you both feel a spark.</div>`;
if(step===2){const timestamp=selectedTimestamp();fields=`<p class="dialog-eyebrow">${icon('heart')} 03 / A DATE TO LOOK FORWARD TO</p><h2 id="dialog-title">A place. A time. A maybe.</h2><p class="dialog-description">One last look before your first hello. This confirms a demo date only; it won’t make a reservation or charge you.</p><div class="review-venue"><img src="assets/${venue.photo}" alt="Illustrative dining space"><div><h3>${venue.name}</h3><p>${venue.area}, Vancouver · fictional sample venue</p></div></div><div class="review-details"><div><span>When</span><span>${dateLabel(timestamp)} · ${displayTime(modal.time)} PT</span></div><div><span>Who</span><span>Mystery match #${esc(currentMatch()?.id||'021')}</span></div><div><span>Your service fee</span><span>C$0 · first introduction</span></div><div><span>Food & drinks</span><span>~C$${venue.price}/person, paid separately</span></div><div><span>Free cancellation until</span><span>${dateLabel(timestamp-86400000)} · ${timeLabel(timestamp-86400000)} PT</span></div></div><div class="inline-note">${icon('shield')}After the 24-hour deadline, a C$20 cancellation/no-show fee would apply. Safety concerns and emergencies are exempt. You can always leave a date. No payments occur in this demo.</div><label class="checkbox-label"><input id="booking-consent" type="checkbox" ${modal.consent?'checked':''}><span>I understand the example cancellation policy and that this is a simulated booking, with simulated acceptance by my match.</span></label>`;}
return `${wizardProgress(step,3)}${fields}<div class="dialog-footer"><button class="button ghost" data-action="${step?'planner-back':'close-modal'}">${step?'← Back':'Maybe later'}</button><button class="button primary" data-action="planner-next" ${step===0&&!venue||step===1&&(modal.dayIndex===null||!modal.time)||step===2&&!modal.consent?'disabled':''}>${step===0?'Find a time':step===1?'One last look':'Confirm demo date'} ${icon(step===2?'heart':'arrow')}</button></div>`;}
function whyModal(){const match=currentMatch();return `<p class="dialog-eyebrow">${icon('spark')} A LITTLE METHOD TO THE MYSTERY</p><h2 id="dialog-title">Common ground.<br>Room for surprise.</h2><p class="dialog-description">Here’s why this sample introduction rose to the top. These are shared foundations, not a promise of chemistry.</p><div class="why-item"><span class="step-icon">${icon('heart')}</span><div><h3>Your intentions line up.</h3><p>${state.profile.intent==='A long-term relationship'?'You’re both looking for a long-term relationship.':'Your sample match is open to getting to know someone new.'}</p></div></div><div class="why-item"><span class="step-icon">${icon('spark')}</span><div><h3>A few little things in common.</h3><p>${match?matchTags().map(esc).join(', '):'Try adjusting your preferences to find a sample match.'}. Your interests and values help shape the introduction.</p></div></div><div class="why-item"><span class="step-icon">${icon('pin')}</span><div><h3>Close enough to make it real.</h3><p>Your age and travel preferences fit. We never show your home address.</p></div></div><div class="inline-note">${icon('lock')}Sample people only. No photo reveal, public profiles, or attractiveness ranking.</div><div class="dialog-footer"><button class="button ghost" data-action="skip-match">Not this time</button><button class="button primary" data-action="plan" ${!match?'disabled':''}>I’m curious ${icon('arrow')}</button></div>`;}
function safetyModal(){return `<p class="dialog-eyebrow">${icon('shield')} THE COMFORT CORNER</p><h2 id="dialog-title">Your comfort<br>comes first. Always.</h2><p class="dialog-description">A good first hello starts with feeling comfortable. You decide what happens next, at every step.</p><ul class="static-list"><li>Meet in a public, staffed venue. Keep your own way home.</li><li>Share your date details with someone you trust.</li><li>You can end a date at any time, without a penalty for leaving.</li><li>Safety-related cancellations and emergencies are exempt from the example cancellation fee.</li><li>In a live service, verification, reports, and support would need a real team behind them.</li></ul><div class="notice-card"><h3>A note about this prototype.</h3><p>People, venues, reviews, and bookings are samples. Verification, payments, and support aren’t connected. Preferences stay in this browser.</p></div><div class="dialog-footer"><button class="button secondary" data-action="report">${icon('flag')} Preview a report</button><button class="button primary" data-action="${state.booking?'share':'close-modal'}">${state.booking?'Copy date details':'Got it'} ${icon(state.booking?'copy':'check')}</button></div>`;}
function cancellationFee(booking,reason,now=Date.now()){return now<=booking.timestamp-86400000||['Safety concern','Emergency'].includes(reason)?0:20;}
function cancelModal(){const booking=state.booking;if(!booking)return '';const free=cancellationFee(booking,modal.reason)===0;return `<p class="dialog-eyebrow">${icon('calendar')} SOMETIMES PLANS CHANGE</p><h2 id="dialog-title">Need a rain check?</h2><p class="dialog-description">You can cancel your demo date here. Your introduction credit will be restored. No actual charge will be made.</p><label class="field-label" for="cancel-reason">What changed?</label><select class="input" id="cancel-reason"><option value="">Choose a reason</option>${['Plans changed','Safety concern','Emergency','I’d prefer another introduction'].map(reason=>`<option ${modal.reason===reason?'selected':''}>${reason}</option>`).join('')}</select><div class="cancellation-fee"><span>Example cancellation fee</span><strong>C$${free?'0':'20'}</strong></div><p class="small-print">${free?'You’re before the 24-hour deadline, or a safety/emergency exception applies.':'You’re within 24 hours of the scheduled date. In a live service, you could appeal the fee.'} In this prototype, cancelling only clears your local demo booking.</p><div class="dialog-footer"><button class="button secondary" data-action="close-modal">Keep my date</button><button class="button dark" data-action="confirm-cancel" ${!modal.reason?'disabled':''}>Cancel demo date</button></div>`;}
function availableDays(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Vancouver',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=type=>parts.find(p=>p.type===type).value;const today=Date.UTC(+get('year'),+get('month')-1,+get('day'),20);return [5,6,7,9].map(offset=>today+offset*86400000);}
function displayTime(time){const [h,m]=time.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`;}
function selectedTimestamp(){const day=availableDays()[modal.dayIndex??0];const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Vancouver',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(day));const get=type=>+parts.find(p=>p.type===type).value;const [hour,minute]=(modal.time||'18:30').split(':').map(Number);const wallTime=Date.UTC(get('year'),get('month')-1,get('day'),hour,minute);let timestamp=wallTime+8*3600000;for(let i=0;i<2;i++){const inVancouver=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Vancouver',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(timestamp));const part=t=>+inVancouver.find(p=>p.type===t).value;const actualWallTime=Date.UTC(part('year'),part('month')-1,part('day'),part('hour'),part('minute'));timestamp+=wallTime-actualWallTime;}return timestamp;}
function updateCountdown(){const target=document.querySelector('[data-countdown]');if(!target||!state.booking)return;const seconds=Math.max(0,Math.floor((state.booking.timestamp-Date.now())/1000));const days=Math.floor(seconds/86400),hours=Math.floor(seconds%86400/3600),minutes=Math.floor(seconds%3600/60);target.textContent=seconds?`${days}d ${String(hours).padStart(2,'0')}h ${String(minutes).padStart(2,'0')}m`:'It’s time for hello.';}
function captureProfileFields(){modalRoot.querySelectorAll('[data-profile-field]').forEach(input=>{modal.draft[input.dataset.profileField]=['age','radius','minAge','maxAge'].includes(input.dataset.profileField)?Number(input.value):input.value.trim();});}
function validateProfileStep(){const p=modal.draft;for(const input of modalRoot.querySelectorAll('input[required]'))if(!input.reportValidity())return false;if(modal.step===0&&(!p.name||p.age<18||p.age>100)){toast('Please enter a first name and an adult age from 18 to 100.');return false;}if(modal.step===1&&(!p.interests.length||!p.values.length)){toast('Choose at least one interest and one quality you value.');return false;}if(modal.step===2&&(p.minAge<18||p.maxAge>100||p.minAge>p.maxAge)){toast('Choose an adult age range with the minimum before the maximum.');return false;}return true;}
async function shareDate(){if(!state.booking){toast('Plan a demo date first to copy its details.');return;}const b=state.booking,v=venueById(b.venueId);const text=`blinddate · DEMO DATE (not a real reservation)\n${v.name}, ${v.area}, Vancouver (fictional venue)\n${dateLabel(b.timestamp,{weekday:'long',month:'long',day:'numeric',year:'numeric'})} at ${timeLabel(b.timestamp)} PT\nMystery match #${b.matchId}\nFree cancellation until ${dateLabel(b.timestamp-86400000)} at ${timeLabel(b.timestamp-86400000)} PT.`;try{await navigator.clipboard.writeText(text);toast('Demo date details copied. Share them with someone you trust.');}catch{const field=document.createElement('textarea');field.value=text;field.className='input';modalRoot.querySelector('.dialog')?.append(field);field.select();toast('Copy the selected demo date details.');}}
document.addEventListener('click',async event=>{
const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;
switch(action){
case'navigate':state.view=button.dataset.view;notificationsOpen=false;save();render();window.scrollTo({top:0,behavior:'instant'});break;
case'notifications':notificationsOpen=!notificationsOpen;state.seenNotifications=true;save();render();break;
case'location':openModal('onboarding',{step:2,draft:structuredClone(state.profile)});break;
case'onboarding':openModal('onboarding',{step:0,draft:structuredClone(state.profile)});break;
case'onboarding-back':captureProfileFields();modal.step--;renderModal();break;
case'onboarding-next':captureProfileFields();if(!validateProfileStep())break;if(modal.step<2){modal.step++;renderModal();modalRoot.querySelector('.dialog').scrollTop=0;}else{state.profile={...modal.draft,complete:true};state.matchIndex=0;save();closeModal();render();toast(eligibleMatches().length?'Your world is saved. A sample introduction is ready.':'Your world is saved. No sample match fits yet; try broadening your preferences.');}break;
case'profile-choice':captureProfileFields();if(button.dataset.multi){const list=modal.draft[button.dataset.group],value=button.dataset.value;modal.draft[button.dataset.group]=list.includes(value)?list.filter(x=>x!==value):[...list,value];}else modal.draft[button.dataset.group]=button.dataset.value;renderModal();break;
case'plan':if(state.booking){closeModal();state.view='dates';save();render();break;}if(!currentMatch()){openModal('onboarding',{step:2,draft:structuredClone(state.profile)});toast('No sample match fits yet. Try a wider age range or travel radius.');break;}openModal('planner',{step:0,filter:'All spots',venueId:null,dayIndex:null,time:null,consent:false});break;
case'reschedule':openModal('planner',{step:0,filter:'All spots',venueId:state.booking.venueId,dayIndex:null,time:null,consent:false,rescheduling:true});break;
case'venue-filter':modal.filter=button.dataset.value;renderModal();break;
case'venue-select':modal.venueId=button.dataset.value;renderModal();break;
case'day-select':modal.dayIndex=Number(button.dataset.value);renderModal();break;
case'time-select':modal.time=button.dataset.value;renderModal();break;
case'planner-back':modal.step--;modal.consent=false;renderModal();break;
case'planner-next':if(modal.step<2){modal.step++;renderModal();modalRoot.querySelector('.dialog').scrollTop=0;}else if(modal.consent){state.booking={venueId:modal.venueId,timestamp:selectedTimestamp(),matchId:state.booking?.matchId||currentMatch().id,createdAt:Date.now()};state.view='dates';save();closeModal();render();window.scrollTo({top:0,behavior:'instant'});toast('Your demo date is set. A little something to look forward to.');}break;
case'why':openModal('why');break;
case'skip-match':state.matchIndex++;save();closeModal();render();toast('A different sample introduction is ready. No cancellation fee applies.');break;
case'how':openModal('how');break;
case'safety':openModal('safety');break;
case'report':openModal('report');break;
case'demo-report':openModal('report-receipt');break;
case'cancel':openModal('cancel',{reason:''});break;
case'confirm-cancel':state.booking=null;save();closeModal();render();toast('Demo date cancelled. Your introduction credit is restored. No charge made.');break;
case'share':await shareDate();break;
case'billing':state.plan=button.dataset.value;save();render();break;
case'select-plan':openModal('plan-preview');break;
case'confirm-plan':state.previewPlan=state.plan;save();closeModal();render();toast('Plan selected for preview. No subscription or charge has been made.');break;
case'reset':openModal('reset');break;
case'confirm-reset':state=defaultState();save();closeModal();render();toast('A fresh start. Your demo has been reset.');break;
case'close-modal':closeModal();break;
}
});
document.addEventListener('change',event=>{if(event.target.id==='booking-consent'){modal.consent=event.target.checked;const button=modalRoot.querySelector('[data-action="planner-next"]');if(button)button.disabled=!modal.consent;}if(event.target.id==='cancel-reason'){modal.reason=event.target.value;renderModal();modalRoot.querySelector('#cancel-reason')?.focus();}});
document.addEventListener('input',event=>{if(event.target.id==='profile-radius')modalRoot.querySelector('#radius-value').textContent=event.target.value;});
modalRoot.addEventListener('click',event=>{if(event.target.classList.contains('dialog-backdrop'))closeModal();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(modal)closeModal();if(notificationsOpen){notificationsOpen=false;render();}}if(event.key==='Tab'&&modal){const focusables=[...modalRoot.querySelectorAll('button:not([disabled]), input, select, textarea, [tabindex="0"]')].filter(el=>el.getClientRects().length);if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&(document.activeElement===first||!modalRoot.contains(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||!modalRoot.contains(document.activeElement))){event.preventDefault();first.focus();}}});
document.addEventListener('click',event=>{if(notificationsOpen&&!event.target.closest('.notification-container')){notificationsOpen=false;render();}});
setInterval(updateCountdown,30000);
render();
